import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第二册：实践与进步 · 全册易错点 · 第25–49课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第二册：实践与进步 · 全册易错点 · 第25–49课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-2/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册易错点 · 第1–24课","link":"/life/english/new-concept/book-2/mistakes-part-01"},"next":{"text":"第二册：实践与进步 · 全册易错点 · 第50–73课","link":"/life/english/new-concept/book-2/mistakes-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册易错点 · 第1–24课","link":"/life/english/new-concept/book-2/mistakes-part-01"},"next":{"text":"第二册：实践与进步 · 全册易错点 · 第50–73课","link":"/life/english/new-concept/book-2/mistakes-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/mistakes-part-02.md","filePath":"life/english/new-concept/book-2/mistakes-part-02.md"}'),l={name:"life/english/new-concept/book-2/mistakes-part-02.md"};function r(i,e,s,h,p,c){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-全册易错点-·-第25–49课" tabindex="-1">第二册：实践与进步 · 全册易错点 · 第25–49课 <a class="header-anchor" href="#第二册-实践与进步-·-全册易错点-·-第25–49课" aria-label="Permalink to &quot;第二册：实践与进步 · 全册易错点 · 第25–49课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="l25-·-间接引语与视角转换" tabindex="-1">L25 · 间接引语与视角转换 <a class="header-anchor" href="#l25-·-间接引语与视角转换" aria-label="Permalink to &quot;L25 · 间接引语与视角转换 {#l25-·-间接引语与视角转换}&quot;">​</a></h2><p>I asked where did it stop 错误；从句应为 where it stopped。</p><p><strong>对照例句：</strong> I asked the driver where the bus stopped.</p><p>asked 带听者 the driver 和间接疑问从句；where 引导地点问题，从句不倒装。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-025">回看讲解和练习</a></p><h2 id="l26-·-一般现在时与习惯" tabindex="-1">L26 · 一般现在时与习惯 <a class="header-anchor" href="#l26-·-一般现在时与习惯" aria-label="Permalink to &quot;L26 · 一般现在时与习惯 {#l26-·-一般现在时与习惯}&quot;">​</a></h2><p>She is liking this style 在一般偏好语境下不自然；常用 She likes this style。</p><p><strong>对照例句：</strong> My sister likes paintings with strong colours.</p><p>likes 表稳定偏好，paintings 是泛指复数，with strong colours 为后置修饰语。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-026">回看讲解和练习</a></p><h2 id="l27-·-过去完成时与先后关系" tabindex="-1">L27 · 过去完成时与先后关系 <a class="header-anchor" href="#l27-·-过去完成时与先后关系" aria-label="Permalink to &quot;L27 · 过去完成时与先后关系 {#l27-·-过去完成时与先后关系}&quot;">​</a></h2><p>had went 错误；had 后用过去分词 gone，不能用过去式 went。</p><p><strong>对照例句：</strong> We had covered the bags before the rain started.</p><p>had covered 标记较早动作，before 从句 started 给出过去参照点；bags 是受保护的物品。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-027">回看讲解和练习</a></p><h2 id="l28-·-动名词与动词搭配" tabindex="-1">L28 · 动名词与动词搭配 <a class="header-anchor" href="#l28-·-动名词与动词搭配" aria-label="Permalink to &quot;L28 · 动名词与动词搭配 {#l28-·-动名词与动词搭配}&quot;">​</a></h2><p>Parking ... block 缺少第三人称单数词尾；一个动名词短语通常按单数看待。</p><p><strong>对照例句：</strong> Parking beside this gate blocks the entrance.</p><p>Parking beside this gate 是动名词短语作主语，整体视为单数，谓语用 blocks。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-028">回看讲解和练习</a></p><h2 id="l29-·-现在完成时与过去时间" tabindex="-1">L29 · 现在完成时与过去时间 <a class="header-anchor" href="#l29-·-现在完成时与过去时间" aria-label="Permalink to &quot;L29 · 现在完成时与过去时间 {#l29-·-现在完成时与过去时间}&quot;">​</a></h2><p>has flew 错误，fly 的过去分词是 flown；本例 carry 的过去分词是 carried。</p><p><strong>对照例句：</strong> The small plane has carried a hundred passengers this week.</p><p>has carried 是现在完成时，a hundred passengers 为累计宾语，this week 连接过去活动与现在。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-029">回看讲解和练习</a></p><h2 id="l30-·-冠词与可数性" tabindex="-1">L30 · 冠词与可数性 <a class="header-anchor" href="#l30-·-冠词与可数性" aria-label="Permalink to &quot;L30 · 冠词与可数性 {#l30-·-冠词与可数性}&quot;">​</a></h2><p>on the river 通常表示在河面上，into the river 强调从外面进入水中。</p><p><strong>对照例句：</strong> A ball landed in the river beside our picnic spot.</p><p>A ball 首次引入对象，the river 是场景内可识别的河流，beside 短语修饰位置。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-030">回看讲解和练习</a></p><h2 id="l31-·-一般现在时与习惯" tabindex="-1">L31 · 一般现在时与习惯 <a class="header-anchor" href="#l31-·-一般现在时与习惯" aria-label="Permalink to &quot;L31 · 一般现在时与习惯 {#l31-·-一般现在时与习惯}&quot;">​</a></h2><p>used to repairing 把过去习惯与 be used to doing 混淆；此处应为 used to repair。</p><p><strong>对照例句：</strong> Mina used to repair bicycles in her parents&#39; garage.</p><p>used to 加原形 repair 表过去习惯，in 后为地点，parents&#39; 是复数所有格。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-031">回看讲解和练习</a></p><h2 id="l32-·-被动语态与信息重点" tabindex="-1">L32 · 被动语态与信息重点 <a class="header-anchor" href="#l32-·-被动语态与信息重点" aria-label="Permalink to &quot;L32 · 被动语态与信息重点 {#l32-·-被动语态与信息重点}&quot;">​</a></h2><p>has found the receipt 是主动；receipt has found 缺少合理宾语且让收据成为发现者。</p><p><strong>对照例句：</strong> The missing receipt has been found behind the counter.</p><p>receipt 是单数承受者，has been found 为完成时被动；behind the counter 说明发现地点。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-032">回看讲解和练习</a></p><h2 id="l33-·-过去完成时与先后关系" tabindex="-1">L33 · 过去完成时与先后关系 <a class="header-anchor" href="#l33-·-过去完成时与先后关系" aria-label="Permalink to &quot;L33 · 过去完成时与先后关系 {#l33-·-过去完成时与先后关系}&quot;">​</a></h2><p>had lost 不表示此后才丢；它把丢地图放在到岸之前。</p><p><strong>对照例句：</strong> By the time we reached the shore, we had lost our map.</p><p>By the time 从句 reached 建立过去参照点，主句 had lost 回顾更早事件，our map 是宾语。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-033">回看讲解和练习</a></p><h2 id="l34-·-间接引语与视角转换" tabindex="-1">L34 · 间接引语与视角转换 <a class="header-anchor" href="#l34-·-间接引语与视角转换" aria-label="Permalink to &quot;L34 · 间接引语与视角转换 {#l34-·-间接引语与视角转换}&quot;">​</a></h2><p>police 通常作复数集合名词：The police are investigating，不用 is。</p><p><strong>对照例句：</strong> The police told me that my bicycle had been found.</p><p>told me 引出接收信息的人；had been found 是从通知时刻回看更早找回动作的被动结构。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-034">回看讲解和练习</a></p><h2 id="l35-·-不定式与目的" tabindex="-1">L35 · 不定式与目的 <a class="header-anchor" href="#l35-·-不定式与目的" aria-label="Permalink to &quot;L35 · 不定式与目的 {#l35-·-不定式与目的}&quot;">​</a></h2><p>stop to run 是停下别的事去跑；stop running 是不再跑。</p><p><strong>对照例句：</strong> A cyclist stopped to help the shop assistant.</p><p>stopped 是主线过去动作，to help 是目的状语，the shop assistant 为 help 的宾语。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-035">回看讲解和练习</a></p><h2 id="l36-·-将来进行时与过程" tabindex="-1">L36 · 将来进行时与过程 <a class="header-anchor" href="#l36-·-将来进行时与过程" aria-label="Permalink to &quot;L36 · 将来进行时与过程 {#l36-·-将来进行时与过程}&quot;">​</a></h2><p>will be swum 是被动形式，不表示她自己正在游；此处用 swimming。</p><p><strong>对照例句：</strong> At noon tomorrow, Ava will be swimming near the eastern coast.</p><p>will be swimming 是将来进行时，At noon tomorrow 给出参照时点，near 表示附近而非已经上岸。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-036">回看讲解和练习</a></p><h2 id="l37-·-被动语态与信息重点" tabindex="-1">L37 · 被动语态与信息重点 <a class="header-anchor" href="#l37-·-被动语态与信息重点" aria-label="Permalink to &quot;L37 · 被动语态与信息重点 {#l37-·-被动语态与信息重点}&quot;">​</a></h2><p>The event will be taken place 错误；take place 本身是不及物表达。</p><p><strong>对照例句：</strong> The new stadium will be opened in September.</p><p>stadium 是被开放的设施，will be opened 为将来被动，in September 表月份。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-037">回看讲解和练习</a></p><h2 id="l38-·-过去完成时与先后关系" tabindex="-1">L38 · 过去完成时与先后关系 <a class="header-anchor" href="#l38-·-过去完成时与先后关系" aria-label="Permalink to &quot;L38 · 过去完成时与先后关系 {#l38-·-过去完成时与先后关系}&quot;">​</a></h2><p>dream of live 错误，介词 of 后若接动词应为 living。</p><p><strong>对照例句：</strong> Before he moved north, Joel had dreamed of a quiet village.</p><p>Before 从句 moved 给出过去参照，had dreamed 回顾更早的愿望；dream of 后接名词短语。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-038">回看讲解和练习</a></p><h2 id="l39-·-间接引语与视角转换" tabindex="-1">L39 · 间接引语与视角转换 <a class="header-anchor" href="#l39-·-间接引语与视角转换" aria-label="Permalink to &quot;L39 · 间接引语与视角转换 {#l39-·-间接引语与视角转换}&quot;">​</a></h2><p>asked whether could he leave 保留了直接问句倒装，应改为 whether he could leave。</p><p><strong>对照例句：</strong> Evan asked the nurse whether he could leave that afternoon.</p><p>whether 引出是否问题，he could leave 为陈述语序；that afternoon 从转述者的视角定位时间。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-039">回看讲解和练习</a></p><h2 id="l40-·-非真实条件句" tabindex="-1">L40 · 非真实条件句 <a class="header-anchor" href="#l40-·-非真实条件句" aria-label="Permalink to &quot;L40 · 非真实条件句 {#l40-·-非真实条件句}&quot;">​</a></h2><p>If I would know 通常不能表达这种标准假设；用 If I knew。</p><p><strong>对照例句：</strong> If I knew more about her work, I would ask better questions.</p><p>knew 表非真实现在假设，would ask 表假设结果；better 是 good 的比较级。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-040">回看讲解和练习</a></p><h2 id="l41-·-情态动词的意义与形式" tabindex="-1">L41 · 情态动词的意义与形式 <a class="header-anchor" href="#l41-·-情态动词的意义与形式" aria-label="Permalink to &quot;L41 · 情态动词的意义与形式 {#l41-·-情态动词的意义与形式}&quot;">​</a></h2><p>need not buy 是不必买，不能译成“不准买”；do not need to buy 也是不必买。</p><p><strong>对照例句：</strong> You need not buy the hat just because it is fashionable.</p><p>need not 在此是情态用法，后接 buy 原形；because 从句说明不应成为唯一理由的因素。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-041">回看讲解和练习</a></p><h2 id="l42-·-动词、宾语与补足语" tabindex="-1">L42 · 动词、宾语与补足语 <a class="header-anchor" href="#l42-·-动词、宾语与补足语" aria-label="Permalink to &quot;L42 · 动词、宾语与补足语 {#l42-·-动词、宾语与补足语}&quot;">​</a></h2><p>watched the bird to move 不合此感官动词结构；主动式通常省略 to。</p><p><strong>对照例句：</strong> We watched the bird move towards the musician&#39;s hand.</p><p>watched 后接宾语 the bird，再接原形 move 作宾语补足语；towards 标记方向。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-042">回看讲解和练习</a></p><h2 id="l43-·-情态动词的意义与形式" tabindex="-1">L43 · 情态动词的意义与形式 <a class="header-anchor" href="#l43-·-情态动词的意义与形式" aria-label="Permalink to &quot;L43 · 情态动词的意义与形式 {#l43-·-情态动词的意义与形式}&quot;">​</a></h2><p>managed landing 不符合常用搭配；用 managed to land。</p><p><strong>对照例句：</strong> The pilot was able to land before the storm arrived.</p><p>was able to land 描述这次成功结果，before 从句限定时间，storm arrived 是之后的事件。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-043">回看讲解和练习</a></p><h2 id="l44-·-真实条件句" tabindex="-1">L44 · 真实条件句 <a class="header-anchor" href="#l44-·-真实条件句" aria-label="Permalink to &quot;L44 · 真实条件句 {#l44-·-真实条件句}&quot;">​</a></h2><p>If we will keep ... 在普通真实条件句中多余；用 If we keep。</p><p><strong>对照例句：</strong> If we keep to the path, we can reach the village before dark.</p><p>if 从句用一般现在时 keep，主句 can reach 表条件下的能力或可能，before dark 为时间界限。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-044">回看讲解和练习</a></p><h2 id="l45-·-被动语态与信息重点" tabindex="-1">L45 · 被动语态与信息重点 <a class="header-anchor" href="#l45-·-被动语态与信息重点" aria-label="Permalink to &quot;L45 · 被动语态与信息重点 {#l45-·-被动语态与信息重点}&quot;">​</a></h2><p>money have been 应为 money has been；不可数名词按单数处理。</p><p><strong>对照例句：</strong> The missing money has been returned in a plain envelope.</p><p>money 不可数，助动词用 has；has been returned 是完成时被动，in 表容器。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-045">回看讲解和练习</a></p><h2 id="l46-·-数量表达与范围" tabindex="-1">L46 · 数量表达与范围 <a class="header-anchor" href="#l46-·-数量表达与范围" aria-label="Permalink to &quot;L46 · 数量表达与范围 {#l46-·-数量表达与范围}&quot;">​</a></h2><p>fewer comfort 不对，comfort 通常不可数；可说 less comfort 或 fewer comfortable seats。</p><p><strong>对照例句：</strong> The overnight train cost more but offered fewer comfortable seats.</p><p>cost 是过去式，与原形同形；more 省略比较中的 money，fewer 修饰可数复数 seats。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-046">回看讲解和练习</a></p><h2 id="l47-·-间接引语与视角转换" tabindex="-1">L47 · 间接引语与视角转换 <a class="header-anchor" href="#l47-·-间接引语与视角转换" aria-label="Permalink to &quot;L47 · 间接引语与视角转换 {#l47-·-间接引语与视角转换}&quot;">​</a></h2><p>evidence 通常不可数，不写 an evidence；可说 a piece of evidence。</p><p><strong>对照例句：</strong> The cellar was said to be haunted, but no one had evidence.</p><p>was said to be 是被动报道结构；but no one had evidence 限定传闻可信度，不确认鬼魂存在。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-047">回看讲解和练习</a></p><h2 id="l48-·-时间、原因与让步从句" tabindex="-1">L48 · 时间、原因与让步从句 <a class="header-anchor" href="#l48-·-时间、原因与让步从句" aria-label="Permalink to &quot;L48 · 时间、原因与让步从句 {#l48-·-时间、原因与让步从句}&quot;">​</a></h2><p>while he removed the mirror 不一定等于拿开之后；表达紧接应使用 as soon as。</p><p><strong>对照例句：</strong> As soon as the dentist removed the mirror, I asked a question.</p><p>As soon as 从句给出先发生的动作，主句 asked 紧接其后；两者都是具体过去事件。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-048">回看讲解和练习</a></p><h2 id="l49-·-叙事中的时态与衔接" tabindex="-1">L49 · 叙事中的时态与衔接 <a class="header-anchor" href="#l49-·-叙事中的时态与衔接" aria-label="Permalink to &quot;L49 · 叙事中的时态与衔接 {#l49-·-叙事中的时态与衔接}&quot;">​</a></h2><p>blowed 不是 blow 的标准过去式，应为 blew；blown 是过去分词。</p><p><strong>对照例句：</strong> I was sleeping on the terrace when a gust blew my blanket away.</p><p>was sleeping 是背景，when 引出 blew；blow 的过去式为 blew，away 表离开原处。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-049">回看讲解和练习</a></p>',128)])])}const g=a(l,[["render",r]]);export{b as __pageData,g as default};
